// Get a list of autostart flows -- flows that can create work, are in covered classes of current class, and have pyInstantiation type set to auto
ParameterPage paramPage = tools.getParameterPage();
ParameterPage paramPageTemp = new ParameterPage();
paramPageTemp.putAll(paramPage);

StringMap casetype = new HashStringMap();
casetype.putString("pxObjClass", "Rule-Obj-CaseType");
casetype.putString("pyClassName", tools.getPrimaryPage().getString("pxObjClass"));
casetype.putString("pyPurpose", "pyDefault");
ParameterPage instParamsPage = new ParameterPage();
instParamsPage.putString("pyCaseTypePurpose", "GETFLOWCALLPARAMS");
instParamsPage.putString("flowType", tools.getParamValue("flowType"));

try {
     tools.doAction(casetype, tools.getPrimaryPage(), instParamsPage);
     ClipboardPage pyCallParams = tools.findPage("pyCallParams");   
     if(pyCallParams != null){
                  	paramPageTemp.putAll(pyCallParams);
		pyCallParams.removeFromClipboard();
     }
       // Call call activity fua.
      pega_rules_utilities.callActivity(tools.getPrimaryPage(),"StartNewFlow", paramPageTemp); 
  } catch (com.pega.pegarules.pub.generator.RuleNotFoundException e) {
	tools.getStepStatus().backoutWorst();
  }
